// План specs/invoices.md 3.1 (кейс .qa/tests/invoices/IN-05). PROD, admin, компания «test», десктоп, EN.
// Только просмотр: открывается существующий счёт и форма New Invoice; Create Invoice не нажимается, позиции не добавляются.
import { test, expect } from '../../fixtures';
import { PROD_ROLE, invoiceNameRow, invoiceNumber, openExistingInvoice, prepareProdTest } from './invoice-helpers';

test.describe('Счета — номер нового счёта (#a901b1)', () => {
  test('Open invoice → Create new → New Invoice without reload opens an empty form (no customer, N/A, no items) #a901b1 @desktop @prod-safe', async ({ asUser }) => {
    const page = await asUser(PROD_ROLE);
    await prepareProdTest(page);

    const prevNumber = await openExistingInvoice(page);
    await expect(page.getByText('Bill To:', { exact: true })).toBeVisible();
    // «Client: <имя>» — есть у счёта с клиентом (у первого в списке может не быть)
    const clientLine = page.getByText(/^Client: /);
    const prevClient = (await clientLine.count()) ? (await clientLine.first().innerText()).replace('Client:', '').trim() : '';

    // Метка в window — пропадёт, если страница перезагрузится
    await page.evaluate(() => { (window as unknown as { __qaNoReload: number }).__qaNoReload = 1; });

    await page.getByRole('button', { name: 'Create new' }).filter({ visible: true }).first().click();
    await page.getByText('New Invoice', { exact: true }).filter({ visible: true }).first().click();
    await page.waitForURL(/\/InvoiceForm\?action=new/i);
    expect(await page.evaluate(() => (window as unknown as { __qaNoReload?: number }).__qaNoReload), 'переход без перезагрузки страницы').toBe(1);

    // Форма пустая (источник: «מה רצוי» — «טופס New Invoice תמיד נפתח ריק»)
    await expect(page.getByRole('button', { name: 'Create Invoice' })).toBeVisible();
    await expect.poll(() => invoiceNumber(page), { message: 'Invoice number нового счёта' }).toBe('N/A');
    await expect(page.getByText('Select a customer', { exact: true })).toBeVisible();
    await expect(page.getByText('Same as billing address', { exact: true })).toBeVisible();
    await expect(page.getByText('No items added yet', { exact: true })).toBeVisible();
    await expect(invoiceNameRow(page).getByRole('button', { name: 'Add name', exact: true })).toBeVisible();
    await expect(page.getByText(/^Client: /), 'строки «Client:» прошлого счёта нет').toHaveCount(0);
    await expect(page.getByText(prevNumber, { exact: true }), `номера прошлого счёта ${prevNumber} на форме нет`).toHaveCount(0);
    if (prevClient) await expect(page.getByText(prevClient, { exact: true }), `клиента прошлого счёта «${prevClient}» на форме нет`).toHaveCount(0);
  });
});
